const NICHE_STATUS_BLOCK_KEYS = Object.keys(NICHE_STATUS);

// Each hall is physically made of separate walls, and the company's own floor plans
// draw them that way: the Frontage runs along the back, with the Right and Left wings
// coming off it, enclosing the hall. (Block L is different — each "section" is one
// free-standing wall, so it renders as a single face.) Showing them as one continuous
// strip of codes hides where one wall ends and the next begins, so each face gets its
// own 2D grid: levels down the side, positions across, exactly like the paper plan.
const WING_META = {
  R: { label: "R · 右 Right Wing", hint: "西侧" },
  F: { label: "F · 正面 Frontage", hint: "背墙" },
  L: { label: "L · 左 Left Wing", hint: "东侧" },
  S: { label: "S · 侧面 Side", hint: "N 座专用" },
  SEC: { label: "整面 Section", hint: "" },
};
// R and L share a price tier, so the wall a niche sits on maps to a coarser pricing side.
const WING_TO_SIDE = { R: "RL", L: "RL", F: "F", S: "S", SEC: "SEC" };

// Agents read the printed plans by wall -- "A1L" is Block A, Hall 1, Left wing -- so the
// search box has to accept that shorthand, not just a bare code. AVAIL_RAW can't answer a
// wall query: it collapses Right and Left into the single pricing side "RL" and loses which
// wall a niche is actually on. NICHE_STATUS keeps it, and the two are generated from the
// same sheet and agree exactly, so the searchable index is built from NICHE_STATUS instead.
// Source order is sheet order (faces as drawn, levels top-down, cells left to right), so
// results are never re-sorted -- iterating the index already lists them the way the paper does.
const [NICHE_AVAIL, NICHE_WALLS] = (() => {
  const rows = [];
  const walls = {}; // wall code -> [{ block, hallcode, wing, total, avail }]
  for (const block of Object.keys(NICHE_STATUS)) {
    for (const hallcode of Object.keys(NICHE_STATUS[block])) {
      for (const face of NICHE_STATUS[block][hallcode]) {
        const wing = face.w;
        // Block L's sections are single free-standing walls with no wing letter, so the
        // wall code is just the section code ("A6"), matching how the sheet labels them.
        const wall = hallcode + (wing === "SEC" ? "" : wing);
        let total = 0;
        let avail = 0;
        for (const row of face.rows) {
          for (const cell of row.cells) {
            if (!cell) continue; // deliberate blank slot in the wall, not a niche
            total += 1;
            if (cell.s !== "A") continue;
            avail += 1;
            rows.push({
              block, hallcode, wing, wall,
              side: WING_TO_SIDE[wing] || wing,
              level: row.level,
              code: cell.c,
              codeNorm: cell.c.replace(/-/g, "").toUpperCase(),
            });
          }
        }
        (walls[wall] = walls[wall] || []).push({ block, hallcode, wing, total, avail });
      }
    }
  }
  return [rows, walls];
})();

// One box has to take every shape an agent might type: a wall ("A1L"), a whole hall ("A1"),
// a whole block ("A"), a bare code ("1032"), or any of those with a code after it
// ("A1L-10-32"). Hyphens are dropped on both sides before comparing because the same idea
// is printed two ways depending on the block -- Block A writes 1032, Block F writes 09-138.
//
// The block may also be written in front ("L-A6"). That matters most for Block L, whose
// sections are named A1..A12, B1..B3, C1..C12 with no "L" anywhere in them -- so the
// natural thing to type is the block plus the section -- and whose A1/A2/A3/B1..B3/C1..C7
// collide by name with real halls in Blocks A, B and C. Without the prefix, "A1" can only
// answer with both blocks at once.
//
// A block prefix is two letters then a digit ("LA6"); a wall is one letter, a digit, then
// the wing ("A1L"). The second character tells them apart, so neither reading is ambiguous.
function parseNicheQuery(raw) {
  const s = raw.trim().toUpperCase().replace(/\s+/g, "");
  if (!s) return null;

  let block = "";
  let rest = s;
  const prefixed = s.match(/^([A-Z])[-·.]?(?=[A-Z]\d)/);
  if (prefixed) {
    block = prefixed[1];
    rest = s.slice(prefixed[0].length);
  }

  const m = rest.match(/^([A-Z])(\d{1,2})([RFLS])?[-·.]?(.*)$/);
  if (m) {
    const [, letter, num, wing, tail] = m;
    return { block, hallcode: letter + num, wing: wing || "", code: tail.replace(/-/g, "") };
  }
  if (/^[A-Z]$/.test(s)) return { block: s, hallcode: "", wing: "", code: "" };
  return { block: "", hallcode: "", wing: "", code: s.replace(/-/g, "") };
}

// A whole block can be thousands of rows; the true count is still reported above the list.
const RESULT_CAP = 200;

function FaceGrid({ face, block, hallcode, qLower, go }) {
  const meta = WING_META[face.w] || { label: face.w, hint: "" };
  const side = WING_TO_SIDE[face.w] || face.w;
  const filterActive = qLower.length > 0;

  const counts = useMemo(() => {
    const c = { total: 0 };
    face.rows.forEach((r) => r.cells.forEach((cell) => {
      if (!cell) return; // blank slot in the wall, not a niche
      c[cell.s] = (c[cell.s] || 0) + 1;
      c.total += 1;
    }));
    return c;
  }, [face]);

  return (
    <div className="mb-3">
      <div className="flex items-baseline justify-between gap-2 mb-1.5 px-0.5">
        <div className="flex items-baseline gap-2" style={{ minWidth: 0 }}>
          <span style={{ color: COLOR.ink, fontFamily: FONT_BODY, fontWeight: 700, fontSize: 12.5 }}>
            {hallcode}{face.w === "SEC" ? "" : face.w}
          </span>
          <span style={{ color: COLOR.inkSoft, fontFamily: FONT_BODY, fontSize: 11 }}>
            {meta.label}{meta.hint && ` · ${meta.hint}`}
          </span>
        </div>
        <span className="flex-shrink-0" style={{ color: COLOR.green, fontFamily: FONT_BODY, fontSize: 11, fontWeight: 700 }}>
          空 {counts.A || 0}
          <span style={{ color: COLOR.inkSoft, fontWeight: 500 }}> / {counts.total}</span>
        </span>
      </div>

      <div className="rounded-xl" style={{ border: `1px solid ${COLOR.line}`, overflowX: "auto" }}>
        <div style={{ width: "max-content" }}>
          {face.rows.map((r) => (
            <div key={r.level} className="flex items-stretch" style={{ borderTop: `1px solid ${COLOR.line}` }}>
              <div className="flex items-center justify-center flex-shrink-0"
                style={{ width: 30, background: COLOR.panel2, color: COLOR.inkSoft, fontFamily: FONT_BODY, fontSize: 10.5, fontWeight: 700, position: "sticky", left: 0, zIndex: 1 }}>
                {r.level}
              </div>
              {r.cells.map((cell, col) => {
                // A null slot is a real blank in the wall, not padding: the sheets leave a
                // gap so the two halves of a wall stay aligned. Keep the space (and skip the
                // cell border) so every column below it stays where the paper puts it.
                if (!cell) {
                  return (
                    <div key={`gap-${col}`} className="flex-shrink-0"
                      style={{ width: 52, background: COLOR.bg }} aria-hidden="true" />
                  );
                }
                const m = NICHE_STATUS_META[cell.s] || NICHE_STATUS_META.X;
                const dim = filterActive && !cell.c.toLowerCase().includes(qLower);
                const cellStyle = {
                  width: 52, padding: "6px 2px", background: m.bg, color: m.color,
                  fontFamily: FONT_BODY, fontSize: 9.5, fontWeight: 700,
                  borderLeft: `1px solid ${COLOR.line}`, opacity: dim ? 0.2 : 1,
                };
                if (cell.s === "A") {
                  return (
                    <button key={cell.c} title={`${cell.c} · ${meta.label} · 点击去计算器`}
                      onClick={() => go("calculator", { block, hallcode, side, level: r.level, code: cell.c }, null, "niche")}
                      className="flex items-center justify-center flex-shrink-0" style={{ ...cellStyle, cursor: "pointer" }}>
                      {cell.c}
                    </button>
                  );
                }
                return (
                  <div key={cell.c} title={`${cell.c} · ${m.label}`} className="flex items-center justify-center flex-shrink-0" style={cellStyle}>
                    {cell.c}
                  </div>
                );
              })}
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}

